<?php
declare(strict_types=1);
if(realpath($_SERVER['SCRIPT_FILENAME']??'')===__FILE__){http_response_code(403);exit;}
function request_form(string $slug,array $row,string $error,bool $sent): void {
 $key=$slug.':booking';$ticket=enquiry_ticket($key);
 if($_SERVER['REQUEST_METHOD']==='GET'||!isset($_SESSION['forms'][$key]['snapshot']))$_SESSION['forms'][$key]['snapshot']=['services'=>$row['services'],'zone'=>$row['time_zone']];
 $catalogue=$_SESSION['forms'][$key]['snapshot']['services'];$zone=$_SESSION['forms'][$key]['snapshot']['zone'];
 $value=fn($k)=>esc(is_string($_POST[$k]??null)?$_POST[$k]:'');
 echo '<section class="public-card" id="booking"><h1>Request a booking</h1><p>Choose your preferred time. Your request is <strong>pending confirmation</strong> until the business confirms it. Availability is not guaranteed.</p>';
 if($error)echo '<p class="alert" role="alert">'.esc($error).'</p>';
 if($sent)echo '<p class="notice" role="status">Request received — pending confirmation. This is not a confirmed booking. The business will review your request.</p>';
 echo '<a href="'.esc(cfg()['base_url'].'/b/'.$slug).'">← Business page</a><div class="request-layout"><form id="booking-request" method="post" action="'.esc(cfg()['base_url'].'/b/'.$slug.'?booking=1').'#booking"><input type="hidden" name="snapshot_hash" value="'.esc(hash('sha256',json_encode($_SESSION['forms'][$key]['snapshot'],JSON_THROW_ON_ERROR))).'"><input type="hidden" name="csrf" value="'.esc($ticket['csrf']).'"><div class="spam-field" aria-hidden="true"><label for="website">Leave blank</label><input id="website" name="website" tabindex="-1" autocomplete="off"></div><nav class="booking-progress" aria-label="Booking progress"><ol><li aria-current="step">1<span>Service</span></li><li>2<span>Details</span></li><li>3<span>Schedule</span></li><li>4<span>Contact</span></li><li>5<span>Review</span></li></ol></nav><p id="step-status" class="step-status" aria-live="polite"></p><fieldset data-step="0"><legend>Service</legend><label for="service">Service</label><select id="service" name="service" required><option value="">Select a service</option>';
 foreach($catalogue['items']??[] as $s)if($s['visible']&&!$s['archived'])echo '<option data-price="'.esc($s['mode']==='quote'?'Quote required':services_price($s,$catalogue['currency'])).'" value="'.esc($s['id']).'"'.(($_POST['service']??'')===$s['id']?' selected':'').'>'.esc($s['name'].' · '.($s['mode']==='quote'?'Quote required':services_price($s,$catalogue['currency']))).'</option>';
 echo '</select><p id="selected-price">Select a service to see pricing.</p>';
 echo '</fieldset><fieldset data-step="1"><legend>Details</legend><label for="address">Service address</label><textarea id="address" name="address" autocomplete="street-address" required minlength="5" maxlength="1000" rows="3">'.$value('address').'</textarea><label for="requirements">Requirements</label><textarea id="requirements" name="requirements" rows="4" required minlength="10" maxlength="2000">'.$value('requirements').'</textarea>';
 if(trim($row['document']['areas']??'')!=='')echo '<p class="coverage-note"><strong>Service areas</strong><br>'.nl2br(esc($row['document']['areas'])).'</p><small>The business will confirm whether your address is covered.</small>';
 echo '</fieldset><fieldset data-step="2"><legend>Schedule</legend><label for="date">Preferred date</label><input id="date" name="date" type="date" min="'.esc((new DateTimeImmutable('now',new DateTimeZone($zone)))->format('Y-m-d')).'" max="2099-12-31" required value="'.$value('date').'"><label for="time">Preferred time</label><input id="time" name="time" type="time" required value="'.$value('time').'"><small>Business time zone: '.esc($zone).'. Preferred time only; no availability reservation.</small></fieldset><fieldset data-step="3"><legend>Contact</legend>';
 foreach(['name'=>['Your name','text','name',120],'email'=>['Email address','email','email',254],'phone'=>['Phone number','tel','tel',40]] as $k=>[$label,$type,$auto,$max])echo '<label for="'.$k.'">'.$label.'</label><input id="'.$k.'" name="'.$k.'" type="'.$type.'" autocomplete="'.$auto.'" maxlength="'.$max.'" '.($k==='name'?'required minlength="2"':'').' value="'.$value($k).'">';

 echo '<small>Provide an email address or phone number.</small></fieldset><fieldset data-step="4"><legend>Review</legend><p>Check your details before sending your request.</p><dl id="booking-review"><dt>Service</dt><dd data-review="service"></dd><dt>Price</dt><dd data-review="price"></dd><dt>Service address</dt><dd data-review="address"></dd><dt>Requirements</dt><dd data-review="requirements"></dd><dt>Preferred schedule</dt><dd data-review="schedule"></dd><dt>Time zone</dt><dd>'.esc($zone).'</dd><dt>Name</dt><dd data-review="name"></dd><dt>Email</dt><dd data-review="email"></dd><dt>Phone</dt><dd data-review="phone"></dd></dl><p><strong>Pending confirmation.</strong> Your preferred time does not reserve availability.</p><p>Your details are shared privately with this business to handle your request. No marketing subscription. <a href="'.esc(cfg()['base_url']).'/privacy.html">Privacy</a></p></fieldset><div class="booking-controls"><button type="button" id="booking-back" hidden>Back</button><button type="button" class="button" id="booking-continue" hidden>Continue</button><button type="submit" class="button" id="booking-send">Send booking request</button></div></form><aside class="request-summary"><details open><summary>Booking summary <span id="summary-price">Choose a service</span></summary><dl><dt>Service</dt><dd id="summary-service">Not selected</dd><dt>Address</dt><dd id="summary-address">Not entered</dd><dt>Preferred schedule</dt><dd id="summary-schedule">Not selected</dd><dt>Time zone</dt><dd id="summary-zone">'.esc($zone).'</dd><dt>Price</dt><dd id="summary-total">Not selected</dd></dl><p>Pending confirmation. No payment is taken.</p></details></aside></div></section>';
}
function request_submit(string $slug): void {
 $key=$slug.':booking';$ticket=enquiry_ticket($key);$snapshot=$ticket['snapshot']??null;
 $origin=parse_url(cfg()['base_url'],PHP_URL_SCHEME).'://'.parse_url(cfg()['base_url'],PHP_URL_HOST);if($port=parse_url(cfg()['base_url'],PHP_URL_PORT))$origin.=':'.$port;
 if((int)($_SERVER['CONTENT_LENGTH']??0)>20000||!is_string($_POST['csrf']??null)||!hash_equals($ticket['csrf'],$_POST['csrf'])||(isset($_SERVER['HTTP_ORIGIN'])&&$_SERVER['HTTP_ORIGIN']!==$origin)||($_SERVER['HTTP_SEC_FETCH_SITE']??'')==='cross-site'||!$snapshot)throw new RuntimeException('This form has expired. Reload before submitting.');
 if(!is_string($_POST['snapshot_hash']??null)||!hash_equals(hash('sha256',json_encode($snapshot,JSON_THROW_ON_ERROR)),$_POST['snapshot_hash']))throw new RuntimeException('Service, price or time zone changed. Reload before submitting.');
 if(($_POST['website']??'')!==''||time()-$ticket['time']<2)throw new RuntimeException('Please wait a moment and try again.');
 $name=enquiry_text('name',2,120);$email=strtolower(enquiry_text('email',0,254));$phone=enquiry_text('phone',0,40);$requirements=enquiry_text('requirements',10,2000);$address=enquiry_text('address',5,1000);
 if(preg_match('/[\r\n\t]/',$name))throw new RuntimeException('Check your name.');
 if($email===''&&$phone==='')throw new RuntimeException('Enter an email address or phone number.');
 if($email!==''&&!filter_var($email,FILTER_VALIDATE_EMAIL))throw new RuntimeException('Enter a valid email address.');
 if($phone!==''&&(!preg_match('/\A[+0-9 ()-]{5,40}\z/',$phone)||strlen(preg_replace('/\D/','',$phone))<5))throw new RuntimeException('Enter a valid phone number.');
 $service=enquiry_text('service',1,32);$s=null;foreach($snapshot['services']['items'] as $item)if($item['id']===$service&&$item['visible']&&!$item['archived'])$s=$item;if(!$s)throw new RuntimeException('Choose an available service.');
 $date=enquiry_text('date',10,10);$time=enquiry_text('time',5,5);$local=$date.' '.$time;$dt=DateTimeImmutable::createFromFormat('!Y-m-d H:i',$local,new DateTimeZone('UTC'));if(!$dt||$dt->format('Y-m-d H:i')!==$local)throw new RuntimeException('Choose a valid preferred schedule.');
 enquiry_ip_limit();api('/rest/v1/rpc/business_booking_request_submit',['p_environment'=>profile_env(),'p_slug'=>$slug,'p_service'=>$service,'p_name'=>$name,'p_email'=>$email,'p_phone'=>$phone,'p_requirements'=>$requirements,'p_request'=>$ticket['request'],'p_address'=>$address,'p_local'=>$local.':00','p_zone'=>$snapshot['zone'],'p_currency'=>$snapshot['services']['currency'],'p_service_snapshot'=>$s]);
 unset($_SESSION['forms'][$key]);$_SESSION['booking_request_sent']=$slug;header('Location: '.cfg()['base_url'].'/b/'.rawurlencode($slug).'?booking=1#booking',true,303);exit;
}
